using System;using System.Collections.Generic;using Game.Components;using Unity.Entities;namespace Game.Runtime{
internal sealed class SourceCampPrefabBinding{internal readonly LogicalCatalogPrefab Logical;internal readonly SourceUnitPrefab Command;internal SourceCampPrefabBinding(LogicalCatalogPrefab logical,SourceUnitPrefab command){Logical=logical;Command=command;}}
internal sealed class SourceCampIdentityMap{
 readonly Dictionary<SourceUnitPrefab,LogicalCatalogPrefab> logical=new Dictionary<SourceUnitPrefab,LogicalCatalogPrefab>();readonly Dictionary<LogicalCatalogPrefab,SourceUnitPrefab> command=new Dictionary<LogicalCatalogPrefab,SourceUnitPrefab>();
 internal SourceCampIdentityMap(EntityManager em,CatalogPrefabStore store,IReadOnlyList<SourceCampPrefabBinding> sourceBindings,bool sourceBindingDomainComplete){if(!sourceBindingDomainComplete||sourceBindings==null)throw new NotSupportedException("Complete authored prefab-to-template identity mapping required");foreach(var x in sourceBindings){if(x?.Logical==null||x.Command==null||!em.Exists(x.Command.Template)||!string.Equals(x.Logical.name,x.Command.name,StringComparison.Ordinal)||logical.ContainsKey(x.Command)||command.ContainsKey(x.Logical))throw new NotSupportedException("Unique same-source prefab/template identity required, no name-only lookup");store.TryGetUnit(x.Logical,out _);logical.Add(x.Command,x.Logical);command.Add(x.Logical,x.Command);}}
 internal LogicalCatalogPrefab Logical(SourceUnitPrefab prefab){if(prefab==null)return null;if(!logical.TryGetValue(prefab,out var p))throw new NotSupportedException("Source command prefab outside closed logical identity map");return p;}internal SourceUnitPrefab Command(LogicalCatalogPrefab prefab){if(prefab==null)return null;if(!command.TryGetValue(prefab,out var p))throw new NotSupportedException("Logical prefab missing actual command/template identity");return p;}}
internal sealed class SourceCampReadScope:IDisposable{[ThreadStatic]internal static SourceCampReadScope Current;internal readonly EntityManager Em;internal readonly SourceCampIdentityMap Map;readonly CatalogMetadataReadScope catalog;
 internal SourceCampReadScope(EntityManager em,CatalogPrefabStore store,CatalogPublicFacts facts,SourceCampIdentityMap map){if(Current!=null)throw new NotSupportedException("Nested availability context unsupported");Em=em;Map=map;using var q=em.CreateEntityQuery(typeof(SkirmishExpandedSessionComponent),typeof(SkirmishProductionCatalogRecord));if(q.CalculateEntityCount()!=1)throw new NotSupportedException("One actual source session/catalog required");var owner=q.GetSingletonEntity();if(em.GetComponentData<SkirmishExpandedSessionComponent>(owner).Phase!=Game.Skirmish.Contracts.SkirmishSessionPhase.Playing)throw new NotSupportedException("Only Playing S002 source availability admitted");var record=em.GetComponentObject<SkirmishProductionCatalogRecord>(owner).Catalog;SourceGroundMissionFamily.RequireCatalogSetup(record?.Setup);catalog=new CatalogMetadataReadScope(em,store,facts,record);Current=this;}
 public void Dispose(){if(!ReferenceEquals(Current,this))throw new InvalidOperationException("Availability context ownership lost");Current=null;catalog.Dispose();}}
internal static class SourceCampCatalogPolicy{internal static bool Allows(EntityManager em,SourceUnitPrefab prefab,bool building){var c=SourceCampReadScope.Current;if(c==null||!ReferenceEquals(c.Em,em))throw new NotSupportedException("Exact retained availability world required");return SourceCatalogPolicy.Allows(em,c.Map.Logical(prefab),building);}}
internal static class SourceCampCatalogTokenAllows{internal static bool Allows(this SkirmishProductionCatalog catalog,SourceUnitPrefab prefab,bool building){var c=SourceCampReadScope.Current;if(c==null||!ReferenceEquals(catalog,CatalogMetadataReadScope.Current.Catalog))throw new NotSupportedException("Exact source catalog reference required");return SourceCampCatalogPolicy.Allows(c.Em,prefab,building);}}
}